1	package org.springframework.samples.petclinic.mapper;
2	
3	import org.jspecify.annotations.NonNull;
4	import org.mapstruct.Mapper;
5	import org.mapstruct.Mapping;
6	import org.springframework.data.domain.Page;
7	import org.springframework.samples.petclinic.model.Owner;
8	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
9	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
10	import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;
11	
12	import java.util.Collection;
13	import java.util.List;
14	
15	/**
16	 * Maps Owner & OwnerDto using Mapstruct
17	 */
18	@Mapper(uses = PetMapper.class)
19	public interface OwnerMapper {
20	
21	    @Mapping(target = "selfLink",
22	        expression = "java(\"/api/owners/\" + owner.getId())")
23	    @Mapping(target = "displayName",
24	        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
25	    @Mapping(target = "initials",
26	        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
27	            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
28	    @Mapping(target = "salutation", expression = "java(salutation(owner))")
29	    @Mapping(target = "checkDigit", expression = "java(checkDigit(owner))")
30	    @Mapping(target = "membershipPoints", expression = "java(membershipPoints(owner))")
31	    @Mapping(target = "membershipLevel", expression = "java(membershipLevel(owner))")
32	    @Mapping(target = "locality", expression = "java(locality(owner))")
33	    @Mapping(target = "timezone", expression = "java(timezone(owner))")
34	    @Mapping(target = "fiscalYear", expression = "java(fiscalYear(owner))")
35	    @Mapping(target = "bulkSignupWarning", expression = "java(bulkSignupWarning(owner))")
36	    @Mapping(target = "contactPreference", expression = "java(contactPreference(owner))")
37	    @Mapping(target = "ageBand", expression = "java(ageBand(owner))")
38	    @Mapping(target = "identityKey",
39	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerIdentity.of(owner))")
40	    @Mapping(target = "telephoneDisplay",
41	        expression = "java(org.springframework.samples.petclinic.rest.function.owner.OwnerTelephone.toDisplay(owner.getTelephone()))")
42	    OwnerDto toOwnerDto(Owner owner);
43	
44	    /**
45	     * Derives the owner's salutation at read time: the stored {@code title} followed by a single
46	     * space and the {@code lastName} when a title was supplied, otherwise just the {@code lastName}.
47	     */
48	    default String salutation(Owner owner) {
49	        String title = owner.getTitle();
50	        if (title == null || title.isBlank()) {
51	            return owner.getLastName();
52	        }
53	        return title + " " + owner.getLastName();
54	    }
55	
56	    /**
57	     * Derives the owner's preferred contact channel at read time: {@code EMAIL} when an email is
58	     * present, otherwise {@code PHONE}.
59	     */
60	    default OwnerDto.ContactPreferenceEnum contactPreference(Owner owner) {
61	        return hasEmail(owner) ? OwnerDto.ContactPreferenceEnum.EMAIL
62	            : OwnerDto.ContactPreferenceEnum.PHONE;
63	    }
64	
65	    /**
66	     * Derives the owner's age band at read time from {@code birthDate}, computed against
67	     * {@code registrationDate} (falling back to the current date when none is stored):
68	     * {@code MINOR} when under 18, {@code ADULT} when 18-64, {@code SENIOR} when 65 or older.
69	     * Returns {@code null} when no birth date was supplied, so the field is absent for owners
70	     * created without one.
71	     */
72	    default OwnerDto.AgeBandEnum ageBand(Owner owner) {
73	        java.time.LocalDate birthDate = owner.getBirthDate();
74	        if (birthDate == null) {
75	            return null;
76	        }
77	        java.time.LocalDate asOf = owner.getRegistrationDate() != null
78	            ? owner.getRegistrationDate() : java.time.LocalDate.now();
79	        int age = java.time.Period.between(birthDate, asOf).getYears();
80	        if (age < 18) {
81	            return OwnerDto.AgeBandEnum.MINOR;
82	        }
83	        if (age < 65) {
84	            return OwnerDto.AgeBandEnum.ADULT;
85	        }
86	        return OwnerDto.AgeBandEnum.SENIOR;
87	    }
88	
89	    /** Whether the owner has a non-blank email address. */
90	    default boolean hasEmail(Owner owner) {
91	        return owner.getEmail() != null && !owner.getEmail().isBlank();
92	    }
93	
94	    /**
95	     * Reports the owner's bulk-signup warning: {@code true} when more than 80 owners had already
96	     * been created on this owner's registration business day at the time it was created. Treats a
97	     * missing value (owners created before this rule existed) as {@code false}.
98	     */
99	    default boolean bulkSignupWarning(Owner owner) {
100	        return Boolean.TRUE.equals(owner.getBulkSignupWarning());
101	    }
102	
103	    /**
104	     * Computes the owner's check digit: a single Luhn check digit (0-9) over the digits contained
105	     * in {@code customerCode}, derived at read time. Returns {@code null} when no customer code has
106	     * been assigned.
107	     */
108	    default Integer checkDigit(Owner owner) {
109	        String customerCode = owner.getCustomerCode();
110	        if (customerCode == null) {
111	            return null;
112	        }
113	        int sum = 0;
114	        boolean dbl = true;
115	        for (int i = customerCode.length() - 1; i >= 0; i--) {
116	            char c = customerCode.charAt(i);
117	            if (c < '0' || c > '9') {
118	                continue;
119	            }
120	            int d = c - '0';
121	            if (dbl) {
122	                d *= 2;
123	                if (d > 9) {
124	                    d -= 9;
125	                }
126	            }
127	            sum += d;
128	            dbl = !dbl;
129	        }
130	        return (10 - (sum % 10)) % 10;
131	    }
132	
133	    /**
134	     * Derives the owner's membership points: starts at 0, adds 2 when an email is present, adds 1
135	     * when the owner had no namesakes at creation ({@code namesakeCount == 0}), adds 2 when the
136	     * owner belongs to a household of 3 or more members ({@code householdSize >= 3}, counted at
137	     * creation by {@code AssignHouseholdSize}), and adds 3 when the owner's tenure is at least one
138	     * elapsed fiscal year (fiscal years start 1 July) since its {@code registrationDate}.
139	     */
140	    default int membershipPoints(Owner owner) {
141	        int points = 0;
142	        if (hasEmail(owner)) {
143	            points += 2;
144	        }
145	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
146	            points += 1;
147	        }
148	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
149	            points += 2;
150	        }
151	        if (tenureFiscalYears(owner) >= 1) {
152	            points += 3;
153	        }
154	        return points;
155	    }
156	
157	    /**
158	     * Maps the owner's {@link #membershipPoints(Owner) membership points} to a numeric level:
159	     * level 1 for 0-1 points, 2 for 2-3, 3 for 4-5, and 4 for 6 or more, then applies the
160	     * household level ceiling (see {@link #uncappedMembershipLevel(Owner)}).
161	     *
162	     * <p>When a {@code membershipLevelCap} was recorded at creation time (by
163	     * {@code CapMembershipLevel}, as one above the maximum level among the owner's existing
164	     * household members), the level is clamped down to that cap. With no cap stored (no existing
165	     * household member when the owner was created) the uncapped level is returned unchanged.
166	     */
167	    default int membershipLevel(Owner owner) {
168	        int level = uncappedMembershipLevel(owner);
169	        Integer cap = owner.getMembershipLevelCap();
170	        if (cap != null && level > cap) {
171	            return cap;
172	        }
173	        return level;
174	    }
175	
176	    /**
177	     * The owner's membership level derived purely from its {@link #membershipPoints(Owner) points},
178	     * before the household level ceiling is applied: level 1 for 0-1 points, 2 for 2-3, 3 for 4-5,
179	     * and 4 for 6 or more.
180	     */
181	    default int uncappedMembershipLevel(Owner owner) {
182	        int points = membershipPoints(owner);
183	        if (points <= 1) {
184	            return 1;
185	        }
186	        if (points <= 3) {
187	            return 2;
188	        }
189	        if (points <= 5) {
190	            return 3;
191	        }
192	        return 4;
193	    }
194	
195	    /**
196	     * The owner's tenure in whole elapsed fiscal years (fiscal years start 1 July): the number of
197	     * 1-July boundaries between its {@code registrationDate} and today, derived via
198	     * {@code FiscalYear} so it matches the fiscal year the membership number and {@code fiscalYear}
199	     * label use. Returns 0 when no registration date is stored (or it lies in the future), so an
200	     * owner with no recorded tenure never qualifies for the tenure-gated points.
201	     */
202	    default long tenureFiscalYears(Owner owner) {
203	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
204	        if (registrationDate == null) {
205	            return 0;
206	        }
207	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear
208	            .elapsed(registrationDate, java.time.LocalDate.now());
209	    }
210	
211	    /**
212	     * The owner's {@code fiscalYear} label, {@code FY<YY>} for the fiscal year (starting 1 July)
213	     * that contains its business-day-adjusted {@code registrationDate}, derived via
214	     * {@code FiscalYear}. Returns {@code null} when no registration date is stored, so the field is
215	     * absent for such owners.
216	     */
217	    default String fiscalYear(Owner owner) {
218	        java.time.LocalDate registrationDate = owner.getRegistrationDate();
219	        if (registrationDate == null) {
220	            return null;
221	        }
222	        return org.springframework.samples.petclinic.rest.function.owner.FiscalYear.label(registrationDate);
223	    }
224	
225	    /**
226	     * Derives the owner's locality (region) at read time from the region-and-hash
227	     * {@code customerCode}: its {@code REGION} prefix (e.g. {@code NSW} for {@code NSW-1A2B3C4D}),
228	     * so the region cannot drift from the identity every other derived value flows through. Owners
229	     * with no {@code customerCode} fall back to resolving the region directly. Both the parse and
230	     * the fallback (including the {@code UNKNOWN} sentinel) live in {@code OwnerCustomerCode}.
231	     */
232	    default String locality(Owner owner) {
233	        String region = org.springframework.samples.petclinic.rest.function.owner.OwnerCustomerCode
234	            .regionOf(owner.getCustomerCode());
